export class Fail extends Error {
  constructor(message) {
    super(message)
    this.name = 'Fail'
    this.exitCode = 2
  }
}

export class CycleError extends Error {
  constructor(cycle) {
    super('cycle')
    this.name = 'CycleError'
    this.cycle = cycle
    this.exitCode = 3
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

