  if (!NAME.test(name)) throw new Fail(`error: line ${lineNo}: invalid task name ${name}`)
}

/**
 * Parse the input text into a graph: a map from name to { cost, deps } where
 * deps is a de-duplicated array of dependency names in first-seen order.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const edges = [] // { name, deps } in input order
  const used = [] // every name a dep line mentions, in input order

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]
    if (directive === 'task') {
      if (words.length !== 3) throw new Fail(`error: line ${lineNo}: expected task <name> <cost>`)
      const [, name, cost] = words
      checkName(lineNo, name)
      if (!COST.test(cost)) throw new Fail(`error: line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new Fail(`error: line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, { cost: Number(cost), deps: [], depSet: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) throw new Fail(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w += 1) checkName(lineNo, words[w])
      const name = words[1]
      const deps = words.slice(2)
      used.push(name, ...deps)
      edges.push({ name, deps })
    } else {
      throw new Fail(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) throw new Fail(`error: unknown task ${name}`)
  }

  for (const edge of edges) {
    const task = tasks.get(edge.name)
    for (const dep of edge.deps) {
      if (!task.depSet.has(dep)) {
        task.depSet.add(dep)
        task.deps.push(dep)
      }
    }
  }

  return tasks
}

/** The task names in ascending order. */
export function sortedNames(tasks) {
  return [...tasks.keys()].sort()
}

/**
 * Find the first cycle a depth-first search meets, starting from each task in
 * ascending name order and walking dependencies in ascending name order.
 * Returns the cycle's names (without the closing repeat) or null.
 */
export function findCycle(tasks) {
  const names = sortedNames(tasks)
  const sortedDeps = new Map(names.map((n) => [n, [...tasks.get(n).deps].sort()]))
  const colour = new Map() // 1 = on the stack, 2 = finished

  for (const root of names) {
    if (colour.has(root)) continue
    const path = [root]
    const stack = [{ name: root, index: 0 }]
    colour.set(root, 1)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const deps = sortedDeps.get(frame.name)
      if (frame.index < deps.length) {
        const dep = deps[frame.index]
        frame.index += 1
        const state = colour.get(dep)
        if (state === 1) return path.slice(path.indexOf(dep))
        if (state === undefined) {
          colour.set(dep, 1)
          path.push(dep)
          stack.push({ name: dep, index: 0 })
        }
      } else {
        colour.set(frame.name, 2)
        path.pop()
        stack.pop()
      }
    }
  }
  return null
}

/** A topological order of the names, dependencies first, ascending where free. */
function topoOrder(tasks) {
  const names = sortedNames(tasks)
  const order = []
  const seen = new Set()
  for (const root of names) {
    if (seen.has(root)) continue
    const stack = [{ name: root, index: 0 }]
    seen.add(root)
