    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const d = info.get(dep)
      if (d.finish > start) start = d.finish
      if (d.depth + 1 > depth) depth = d.depth + 1
    }
    const finish = start + task.cost
    info.set(name, { start, finish, depth })
