import { priorities, sortedNames } from './graph.js'

/**
 * Run the graph on `workerCount` workers and return, for each worker index,
 * the runs it performed as { name, start, finish }, plus the makespan.
 */
export function pack(tasks, workerCount) {
  const names = sortedNames(tasks)
  const priority = priorities(tasks)
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finished = new Map()
  const pending = new Set(names)
  let makespan = 0
  let time = 0

  while (pending.size > 0) {
    for (;;) {
      let worker = -1
      for (let i = 0; i < workerCount; i += 1) {
        if (freeAt[i] <= time) {
          worker = i
          break
        }
      }
      if (worker < 0) break

      let chosen = null
      let chosenPriority = -1
      for (const name of names) {
        if (!pending.has(name)) continue
        let ready = true
        for (const dep of tasks.get(name).deps) {
          const f = finished.get(dep)
          if (f === undefined || f > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        const p = priority.get(name)
        if (p > chosenPriority) {
          chosenPriority = p
          chosen = name
        }
      }
      if (chosen === null) break

      const cost = tasks.get(chosen).cost
      const finish = time + cost
      runs[worker].push({ name: chosen, start: time, finish })
      freeAt[worker] = finish
      finished.set(chosen, finish)
      pending.delete(chosen)
      if (finish > makespan) makespan = finish
    }

    if (pending.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i += 1) {
      if (freeAt[i] > time && freeAt[i] < next) next = freeAt[i]
    }
    if (next === Infinity) break
    time = next
  }

  return { runs, makespan }
}
"}

