{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { analyse, CycleError, Fail, findCycle, parse, sortedNames } from './graph.js'
import { pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new Fail('error: workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new Fail(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function render(options, tasks) {
  const out = []
  if (options.mode === 'pack') {
    const { runs, makespan } = pack(tasks, options.workers)
    for (let i = 0; i < runs.length; i += 1) {
      let line = `worker ${i}:`
      for (const run of runs[i]) line += ` ${run.name}@${run.start}-${run.finish}`
      out.push(line)
    }
    out.push(`makespan ${makespan}`)
    return out
  }

  const { info, total } = analyse(tasks)
  const names = sortedNames(tasks)
  if (options.mode === 'waves') {
    const waves = []
    for (const name of names) {
      const depth = info.get(name).depth
      if (waves[depth] === undefined) waves[depth] = []
      waves[depth].push(name)
    }
    for (let k = 0; k < waves.length; k += 1) {
      out.push(`wave ${k}: ${(waves[k] || []).join(' ')}`)
    }
  } else {
    for (const name of names) {
      const { start, finish, depth } = info.get(name)
      out.push(`${name} start=${start} finish=${finish} depth=${depth}`)
    }
  }
  out.push(`total ${total}`)
  return out
}

function main() {
  const options = parseArgs(process.argv.slice(2))
  const tasks = parse(readStdin())
  const cycle = findCycle(tasks)
  if (cycle) throw new CycleError(cycle)
  const lines = render(options, tasks)
  process.stdout.write(lines.length === 0 ? '' : `${lines.join('\n')}\n`)
}

try {
  main()
} catch (error) {
  if (error instanceof CycleError) {
    process.stderr.write(`error: cycle: ${[...error.cycle, error.cycle[0]].join(' -> ')}\n`)
    process.exit(3)
  }
  if (error instanceof Fail) {
    process.stderr.write(`${error.message}\n`)
    process.exit(2)
  }
  throw error
}
"}

